package adminapi

import (
	"net/http"
)

func (s *Server) configCapacity(w http.ResponseWriter, r *http.Request) {
	rows, e := s.DB.QueryContext(r.Context(), `SELECT u.panel_id::text,pi.base_url,u.inbound_id,u.port,u.target_users,u.active_users,u.expired_users,u.quota_exhausted_users,u.deficit,u.created_last_cycle,u.deleted_last_cycle,u.last_error,u.observed_at FROM user_capacity_snapshots u JOIN panel_instances pi ON pi.id=u.panel_id ORDER BY pi.base_url,u.port`)
